probe(Number.isInteger(slots.lastMinutes) && slots.lastMinutes > 0, "the last ticket must have a positive whole number of minutes before closing");
const minutesOf = (clock) => {
  const parts = clock.split(":");
  return Number(parts[0]) * 60 + Number(parts[1]);
};
const order = [slots.wanted.minutes < slots.alternative.minutes ? "wanted" : "alternative", slots.alternative.minutes < slots.wanted.minutes ? "alternative" : "wanted"];
const best = order[0];
const runnerUp = order[1];
probe(best !== runnerUp, "the two tickets must not share one of the listed hours");
