const slots = $slots;
probe(typeof slots === "object" && slots !== null, "the case must carry the parsed counter hours");
probe(typeof slots.person === "string" && slots.person.length > 0, "the case must name the person who asks for the ticket");
probe(typeof slots.place === "string" && slots.place.length > 0, "the case must name the counter hours place");
probe(Array.isArray(slots.to) && slots.to.length === 2, "the closing window must be printed in the format HH:MM–HH:MM");
probe(slots.from[0] !== slots.to[0] && slots.from[1] !== slots.to[1], "the two-day window must run from different hours");
probe(slots.noTickets === true, "the break must be the only ticket break in this section");
probe(slots.tickets.length === 2, "the section must offer exactly two tickets");
const ticket = slots.tickets.find((t) => t.day === slots.person);
probe(ticket !== undefined, "the person must have a listed ticket for this section");
const windows = [];
for (const hour of ["09:00", "10:00", "11:00"]) {
  const open = Math.max(0, slots.from[0].indexOf(hour) - slots.lastMinutes);
  const close = Math.min(slots.to.length, slots.from[1].length - slots.lastMinutes);
  if (open <= 0 || close < open) { continue; }
  windows.push({ hour: hour, open: open, close: close });
}
probe(windows.length === 2, "the section must break the window on both hours");
const chosen = windows.find((w) => w.open === 0 && w.close === 0);
probe(chosen !== undefined, "one day break must cover both hours");
const from = Math.max(0, slots.from[0].indexOf(chosen.hour) - slots.lastMinutes);
const until = Math.min(slots.to.length, slots.from[1].length - slots.lastMinutes);
const ticket = { day: chosen.hour, from: from, until: until };
return "Break " + chosen.hour + ": " + from + "–" + until + " min. No tickets.";

