probe(Number.isInteger(slots.runMinutes) && slots.runMinutes > 0, "the run time must be a positive whole number of minutes");
const throughputHours = slots.nominal throughput / 100;
const outputMicrobes = Math.round(throughputHours * slots.overheadPercent);
probe(outputMicrobes > 0, "the overhead must produce a positive number of useful output units");
const usefulUnits = Math.floor(outputMicrobes / slots.runMinutes);
probe(usefulUnits > 0, "the process must run at least one minute to use up the output");
const rateHundredths = Math.round(100 * outputMicrobes / slots.runMinutes);
const fmt = (value) => {
  const whole = Math.floor(value / 100);
  const fraction = value % 100;
  if (fraction === 0) { return String(whole); }
  if (fraction % 10 === 0) { return whole + "." + (fraction / 10); }
  return whole + "." + (fraction < 10 ? "0" + fraction : String(fraction));
};
return "The useful output is " + fmt(usefulUnits) + " " + slots.runMinutes + "-minute units at " + slots.overheadPercent + "% of the throughput.";

