const slots = $slots;
const adjacency = new Map();
for (const relation of slots.relations) {
  if (!adjacency.has(relation.row)) {
    adjacency.set(relation.row, []);
  }
  adjacency.get(relation.row).push(relation.to);
}
const seen = new Set([slots.start]);
let frontier = [slots.start];
let distance = 0;
while (frontier.length > 0 && !seen.has(slots.target)) {
  distance += 1;
  const next = [];
  for (const current of frontier) {
    for (const edge of adjacency.get(current) || []) {
      if (edge.to === slots.target) {
        seen.add(edge.to);
        next.push(edge.to);
      }
    }
  }
  frontier = next;
}
if (!seen.has(slots.target)) {
  throw new Error("the target cannot be reached through the given relations");
}
const path = [slots.start];
let node = slots.target;
while (adjacency.has(node) && seen.has(node)) {
  const next = [];
  for (const edge of adjacency.get(node) || []) {
    if (seen.has(edge.to)) {
      continue;
    }
    seen.add(edge.to);
    next.push(edge.to);
  }
  frontier = next;
  path.push(node);
}
return distance + " unit steps.";

